// Get the incoming item from the Webhook
const input = $input.first().json;

// n8n Webhooks normally place submitted JSON inside "body".
// This fallback also supports directly received JSON.
let body =
  input.body !== undefined
    ? input.body
    : input;

// Handle the unlikely case that the body arrives as a JSON string
if (typeof body === "string") {
  try {
    body = JSON.parse(body);
  } catch {
    body = {};
  }
}

// Replace missing Voiceflow values with a default
function clean(value, defaultValue = "Not specified") {
  if (value === undefined || value === null) {
    return defaultValue;
  }

  const text = String(value).trim();

  if (text === "" || text === "0") {
    return defaultValue;
  }

  return text;
}

// Normalise Yes/No fields
function cleanYesNo(value, defaultValue = "No") {
  const text = clean(value, defaultValue).toLowerCase();

  return text === "yes" ? "Yes" : "No";
}

// Normalise information status
function cleanInformationStatus(value) {
  const text = clean(value, "Unavailable").toLowerCase();

  return text === "verified"
    ? "Verified"
    : "Unavailable";
}

// Normalise the final request status
function cleanRequestStatus(value, followUpRequested, informationStatus) {
  const text = clean(value, "").toLowerCase();

  if (
    followUpRequested === "Yes" ||
    text === "follow-up requested" ||
    text === "follow up requested"
  ) {
    return "Follow-up Requested";
  }

  if (
    informationStatus === "Unavailable" ||
    text === "information unavailable"
  ) {
    return "Information Unavailable";
  }

  return "Answered";
}

// Generate submission date and timestamp.
// Prefer a supplied business timezone; fall back to UTC.
const requestedSubmissionTimezone = clean(
  body.business_timezone ??
  body.submission_timezone,
  "UTC"
);

let submissionTimezone = requestedSubmissionTimezone;

try {
  new Intl.DateTimeFormat("en-US", {
    timeZone: submissionTimezone
  }).format(new Date());
} catch {
  submissionTimezone = "UTC";
}

const now = new Date();

const parts = new Intl.DateTimeFormat("en-GB", {
  timeZone: submissionTimezone,
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hourCycle: "h23"
}).formatToParts(now);

const getPart = (type) =>
  parts.find((part) => part.type === type)?.value;

const year = getPart("year");
const month = getPart("month");
const day = getPart("day");
const hour = getPart("hour");
const minute = getPart("minute");
const second = getPart("second");

const dateSubmitted = `${year}-${month}-${day}`;
const timestamp =
  `${dateSubmitted} ${hour}:${minute}:${second}`;

// Generate a unique incentive-request ID
const randomPart = Math.random()
  .toString(36)
  .slice(2, 8)
  .toUpperCase();

const incentiveRequestId =
  `INCENTIVE-${year}${month}${day}-${Date.now()}-${randomPart}`;

// Normalise linked values
const informationStatus = cleanInformationStatus(
  body.information_status
);

const followUpRequested = cleanYesNo(
  body.follow_up_requested
);

const requestStatus = cleanRequestStatus(
  body.request_status,
  followUpRequested,
  informationStatus
);

// Return one flattened item for Google Sheets
return [
  {
    json: {
      incentive_request_id: incentiveRequestId,

      // Contact details are handled in the separate
      // Leave a Message for Justin workflow.
      name: "Not specified",

      phone: "Not specified",

      email: "Not specified",

      community: clean(body.community),

      property: clean(body.property),

      incentive_topic: clean(
        body.incentive_topic
      ),

      incentive_question: clean(
        body.incentive_question
      ),

      information_status: informationStatus,

      answer_summary: clean(
        body.answer_summary
      ),

      financing_method: clean(
        body.financing_method
      ),

      preferred_lender_status: clean(
        body.preferred_lender_status
      ),

      move_in_or_closing_timeline: clean(
        body.move_in_or_closing_timeline
      ),

      follow_up_requested: followUpRequested,

      // These are collected separately when follow-up is requested.
      preferred_contact_method: "Not specified",

      best_time_to_contact: "Not specified",

      request_status: requestStatus,

      submission_timezone: submissionTimezone,

      date_submitted: dateSubmitted,

      timestamp: timestamp
    }
  }
];
